<script setup lang="ts">
definePageMeta({ layout: 'admin' })
const router=useRouter();const {data:dashboard,refresh,pending}=await useDashboard();const stats=computed(()=>dashboard.value?.stats??[]);const activity=computed(()=>dashboard.value?.activity??[]);const contents=computed(()=>dashboard.value?.recentContents??[]);const filterOpen=ref(false);const selectedStatus=ref('');const filteredContents=computed(()=>selectedStatus.value?contents.value.filter(x=>x.status===selectedStatus.value):contents.value)
async function exportData(){const api=useApi();const names=['games','teams','events','gallery','players','staff','board','members','sponsors','opportunities'];const all:any={exportedAt:new Date().toISOString()};for(const name of names)all[name]=await api(`/api/${name}`);const blob=new Blob([JSON.stringify(all,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`gdcss-cms-${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(url)}
</script>
<template><div class="page-stack"><section class="page-heading"><div><p class="eyebrow">Visão geral</p><h1>Painel de controlo</h1><p class="page-heading__description">Dados reais da plataforma e conteúdos geridos pelo CMS.</p></div><div class="page-heading__actions"><button class="btn btn--secondary" @click="exportData"><Icon name="lucide:download" size="17"/> Exportar</button><button class="btn btn--primary" @click="router.push('/admin/eventos?new=1')"><Icon name="lucide:plus" size="17"/> Novo conteúdo</button></div></section><section class="stats-grid" aria-label="Estatísticas"><CmsStatCard v-for="stat in stats" :key="stat.label" v-bind="stat"/></section><section class="dashboard-grid"><article class="panel panel--activity"><div class="panel__header"><div><h2>Atividade editorial</h2><p>Alterações reais nos últimos 7 dias</p></div><button class="text-button" @click="refresh"><Icon name="lucide:refresh-cw"/> Atualizar</button></div><div v-if="pending" class="cms-loading">A carregar…</div><div v-else class="bar-chart" aria-label="Atividade editorial"><div v-for="(value,index) in activity" :key="index" class="bar-chart__item"><div class="bar-chart__track"><span :style="{height:`${Math.max(4,Math.min(100,value*18))}%`}"/></div><small>{{['S','T','Q','Q','S','S','D'][index]}} · {{value}}</small></div></div></article><article class="panel quick-actions"><div class="panel__header"><div><h2>Ações rápidas</h2><p>Atalhos funcionais</p></div></div><button class="quick-action" @click="router.push('/admin/jogos?new=1')"><span><Icon name="lucide:calendar-plus" size="18"/></span><div><strong>Adicionar jogo</strong><small>Calendário e jornadas</small></div><Icon name="lucide:chevron-right"/></button><button class="quick-action" @click="router.push('/admin/media')"><span><Icon name="lucide:image-plus" size="18"/></span><div><strong>Carregar media</strong><small>Imagens e documentos</small></div><Icon name="lucide:chevron-right"/></button><button class="quick-action" @click="router.push('/admin/utilizadores?new=1')"><span><Icon name="lucide:user-plus" size="18"/></span><div><strong>Adicionar utilizador</strong><small>Gerir acessos</small></div><Icon name="lucide:chevron-right"/></button></article></section><section class="panel content-panel"><div class="panel__header content-panel__header"><div><h2>Próximos jogos</h2><p>Agenda obtida da mesma fonte de dados do site</p></div><div class="content-panel__tools"><button class="filter-button" @click="filterOpen=!filterOpen"><Icon name="lucide:sliders-horizontal"/> Filtrar</button><button class="text-button" @click="router.push('/admin/jogos')">Ver todos <Icon name="lucide:arrow-right"/></button></div></div><div v-if="filterOpen" style="padding:0 24px 16px"><select v-model="selectedStatus" class="filter-button"><option value="">Todos os estados</option><option value="Agendado">Agendado</option><option value="Terminado">Terminado</option></select></div><div v-if="!filteredContents.length" class="empty-state"><h3>Sem jogos</h3><p>Não existem jogos para apresentar.</p></div><div v-else class="table-scroll"><table class="data-table"><thead><tr><th>Jogo</th><th>Jornada</th><th>Estado</th><th>Hora</th><th>Data</th><th>Ações</th></tr></thead><tbody><tr v-for="item in filteredContents" :key="item.id"><td><strong>{{item.title}}</strong></td><td>{{item.category}}</td><td><CmsBadge :label="item.status" :tone="item.tone"/></td><td>{{item.author}}</td><td class="mono">{{item.updated}}</td><td><button class="icon-button icon-button--small" aria-label="Abrir jogos" @click="router.push('/admin/jogos')"><Icon name="lucide:arrow-up-right"/></button></td></tr></tbody></table></div></section></div></template>
